//autogenerated:yes
//nolint:revive,govet,errcheck
package avssuas_test

import (
	"testing"

	dialectpkg "github.com/bluenviron/gomavlib/v4/pkg/dialects/avssuas"
	"github.com/stretchr/testify/require"
)

func TestEnum_AVSS_HORSEFLY_OPERATION_MODE(t *testing.T) {
	t.Run("zero", func(t *testing.T) {
		var e dialectpkg.AVSS_HORSEFLY_OPERATION_MODE
		e.UnmarshalText([]byte{})
		e.MarshalText()
		e.String()
	})

	t.Run("first entry", func(t *testing.T) {
		enc, err := dialectpkg.MODE_HORSEFLY_MANUAL_CTRL.MarshalText()
		require.NoError(t, err)

		var dec dialectpkg.AVSS_HORSEFLY_OPERATION_MODE
		err = dec.UnmarshalText(enc)
		require.NoError(t, err)

		require.Equal(t, dialectpkg.MODE_HORSEFLY_MANUAL_CTRL, dec)
	})
}
